def find_exploded_player(K, N, outcomes):
    players = list(range(1, 9))
    current_player_index = K - 1

    for _, outcome in outcomes:
        if outcome == "T":
            current_player_index = (current_player_index + 1) % 8
        elif outcome == "N":
            pass
        elif outcome == "P":
